import{_ as p,a0 as d,w as a,s as e,I as o,x as n,a1 as i,A as u,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"在UEFI模式下安装Ubuntu 14.04与Windows 8/8.1双启动 | LCTT x X-CMD","titleTemplate":false,"description":"在UEFI模式下安装Ubuntu 14.04与Windows 8/8.1双启动 | LCTT (201406) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在UEFI模式下安装Ubuntu 14.04与Windows 8/8.1双启动 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在UEFI模式下安装Ubuntu 14.04与Windows 8/8.1双启动 | LCTT (201406) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201406/Guide To Install Ubuntu 14.04 In Dual Boot Mode With Windows 8 Or 8.1 UEFI","title":"在UEFI模式下安装Ubuntu 14.04与Windows 8/8.1双启动","tag":"201406","desc":""},"relativePath":"201406/Guide To Install Ubuntu 14.04 In Dual Boot Mode With Windows 8 Or 8.1 UEFI.md","filePath":"[post].md"}'),r={name:"201406/Guide To Install Ubuntu 14.04 In Dual Boot Mode With Windows 8 Or 8.1 UEFI.md"};function w(b,t,U,m,f,g){const s=d("Link");return a(),e("div",null,[t[25]||(t[25]=o("h1",{id:"在uefi模式下安装ubuntu-14-04与windows-8-8-1双启动",tabindex:"-1"},[n("在UEFI模式下安装Ubuntu 14.04与Windows 8/8.1双启动 "),o("a",{class:"header-anchor",href:"#在uefi模式下安装ubuntu-14-04与windows-8-8-1双启动","aria-label":"Permalink to “在UEFI模式下安装Ubuntu 14.04与Windows 8/8.1双启动”"},"​")],-1)),t[26]||(t[26]=o("p",null,[o("img",{src:"http://itsfoss.com/wp-content/uploads/2014/05/Dual_Boot_Windows8_Ubuntu_1404.jpeg",alt:""})],-1)),o("p",null,[t[1]||(t[1]=n("之前我已经写过关于",-1)),i(s,{href:"http://itsfoss.com/install-ubuntu-dual-boot-mode-windows/"},{default:u(()=>[...t[0]||(t[0]=[n("如何安装Ubuntu Linux和Windows 7",-1)])]),_:1}),t[2]||(t[2]=n("以及8的双启动，但是那些教程不包含那些预装Windows 8的系统。那些较新的预装了Windows 8或Windows 8.1的系统使用了UEFI来替代BIOS。这使得安装双启动变得和之前的常规方法有点不同。在这个教程中，我们将看到",-1)),t[3]||(t[3]=o("strong",null,"如何在UEFI模式下安装Ubuntu 14.04与Windows 8/8.1双启动",-1)),t[4]||(t[4]=n("。",-1))]),t[27]||(t[27]=o("p",null,"这个教程是在一台新买的戴尔灵越 7437（酷睿i7第四代处理器， 256GB SSD，8GB内存以及内置1GB(共享内存) Intel显卡）上演示的。为了使你能够成功安装UEFI下Linux和Windows 8的双启动，我会提到你需要做的所有步骤。如果你已经完成这些步骤中的部分步骤，直接跳到下一步。如果你有个全新的系统，那就更好了。",-1)),t[28]||(t[28]=o("p",null,"在这里提到的这些步骤也适用于其它基于Ubuntu的Linux发行版，如Linux Mint，Elementary OS等等。不多说，让我们来看看如何在启用了UEFI安全启动的Windows 8系统上双启动Linux。",-1)),t[29]||(t[29]=o("h3",{id:"让-ubuntu-14-04-和-windows-8-双启动",tabindex:"-1"},[n("让 Ubuntu 14.04 和 Windows 8 双启动： "),o("a",{class:"header-anchor",href:"#让-ubuntu-14-04-和-windows-8-双启动","aria-label":"Permalink to “让 Ubuntu 14.04 和 Windows 8 双启动：”"},"​")],-1)),t[30]||(t[30]=o("p",null,"要在一个UEFI系统上安装Ubuntu有多方面的前提条件。让我们来一个一个看：",-1)),t[31]||(t[31]=o("h4",{id:"第一步-做个备份-可选",tabindex:"-1"},[n("第一步：做个备份 [可选] "),o("a",{class:"header-anchor",href:"#第一步-做个备份-可选","aria-label":"Permalink to “第一步：做个备份 [可选]”"},"​")],-1)),o("p",null,[t[6]||(t[6]=n("做个备份总是个不错的选择，防止你把系统弄糟了。网上有众多文章教你如何备份系统。你可以参照",-1)),i(s,{href:"http://www.makeuseof.com/tag/6-safest-ways-to-backup-restore-your-files-in-windows-7-8/"},{default:u(()=>[...t[5]||(t[5]=[n("这个教程",-1)])]),_:1}),t[7]||(t[7]=n("。",-1))]),t[32]||(t[32]=o("h4",{id:"第二步-创建一个ubuntu的usb启动盘-光盘启动盘",tabindex:"-1"},[n("第二步：创建一个Ubuntu的USB启动盘/光盘启动盘 "),o("a",{class:"header-anchor",href:"#第二步-创建一个ubuntu的usb启动盘-光盘启动盘","aria-label":"Permalink to “第二步：创建一个Ubuntu的USB启动盘/光盘启动盘”"},"​")],-1)),o("p",null,[t[9]||(t[9]=n("你需要做的下一件事是创建一个USB启动盘或光盘启动盘。我推荐在Windows下使用",-1)),i(s,{href:"http://www.pendrivelinux.com/universal-usb-installer-easy-as-1-2-3/"},{default:u(()=>[...t[8]||(t[8]=[n("Universal USB Installer",-1)])]),_:1}),t[10]||(t[10]=n("创建一个Linux OS的USB启动盘。",-1))]),t[33]||(t[33]=l('<h4 id="第三步-为ubuntu划分一块安装分区" tabindex="-1">第三步：为Ubuntu划分一块安装分区 <a class="header-anchor" href="#第三步-为ubuntu划分一块安装分区" aria-label="Permalink to “第三步：为Ubuntu划分一块安装分区”">​</a></h4><p>假设你有一个全新的系统，我们要做的第一件事是创建一个分区来安装Linux。我系统中的256GB磁盘出厂时就有若干个分区，但主要是用来备份及其它目的的。主分区是安装了Windows 8.1的C盘，约有220GB。</p><p>如果你也像这样只有一个分区，你需要从中分割出一些空间给Linux。如果你有若干空间大小足够的分区，可以使用它们中除C盘外的任意盘，因为安装时会抹掉其中的数据。</p><p>要在Windows 8中创建分区，需要使用磁盘管理工具。你可以通过在控制面板中搜索‘磁盘’找到磁盘管理工具。</p><p><img src="http://itsfoss.com/wp-content/uploads/2014/05/disk_partition.jpeg" alt=""></p><p>在磁盘管理工具中，右键点击你想划分并缩小的卷。在我的演示中，我选择C盘的卷进行缩小，划分出未分配空间：</p><p><img src="http://itsfoss.com/wp-content/uploads/2014/05/disk_partition_Windows8.jpeg" alt=""></p><p>缩小后出现的未分配空间就放在那里好了，不用对其分区和格式化。我们会在安装Ubuntu时用到它。</p><h4 id="第四步-在windows中禁用快速启动-可选" tabindex="-1">第四步：在Windows中禁用快速启动 [可选] <a class="header-anchor" href="#第四步-在windows中禁用快速启动-可选" aria-label="Permalink to “第四步：在Windows中禁用快速启动 [可选]”">​</a></h4><p>为了实现快速启动，Windows 8引进了叫做“快速启动”的新特性。尽管不是强制要求，最好还是将其禁用。</p><p>打开<strong>控制面板 &gt; 硬件与声音 &gt; 电源选项 &gt; 选择电源按钮的功能 &gt; 更改当前不可用的设置</strong>，取消选中<strong>启用快速启动（推荐）</strong>。</p><h4 id="第五步-禁用windows-8-and-8-1的安全启动-secure-boot" tabindex="-1">第五步：禁用Windows 8 and 8.1的安全启动（secure boot） <a class="header-anchor" href="#第五步-禁用windows-8-and-8-1的安全启动-secure-boot" aria-label="Permalink to “第五步：禁用Windows 8 and 8.1的安全启动（secure boot）”">​</a></h4><p>这是最重要的步骤。Windows 8新的安全启动（secure boot）原本是针对rootkit病毒的安全特性，但它也阻止了Windows和Linux的双启动。为了实现Windows和Linux的双启动，我们必须在UEFI中禁用安全启动（secure boot）。</p>',13)),o("p",null,[t[12]||(t[12]=n("可以参见：",-1)),i(s,{href:"http://linux.cn/article-3061-1.html"},{default:u(()=>[...t[11]||(t[11]=[n("如何在 Win8 上禁用 UEFI 安全引导以安装Linux",-1)])]),_:1}),t[13]||(t[13]=n("。",-1))]),t[34]||(t[34]=l('<h4 id="第六步-安装ubuntu-与windows-8共存" tabindex="-1">第六步：安装Ubuntu，与Windows 8共存 <a class="header-anchor" href="#第六步-安装ubuntu-与windows-8共存" aria-label="Permalink to “第六步：安装Ubuntu，与Windows 8共存”">​</a></h4><p>一旦你禁用了安全启动（secure boot），那就是时候安装Ubuntu了。我希望你像第二步中提到的一样创建了一个USB启动盘。插入U盘，然后从U盘启动系统。</p><p>要从USB启动，需要在Windows中选择从USB启动的选项。从电脑设置（像UEFI）中选择选项或在点击“重新启动”的时候按住Shift键。</p><p>当你用USB启动盘启动后，你会看到试用（try）或者安装（install）Ubuntu的选择，这里要点击“安装”。另外在屏幕上不多的设置选项里面，你可以选择你用的语言。接下来是关于硬盘空间，电源和网络连接等等的一些检查。只需点击<strong>继续</strong>。</p><p><img src="http://itsfoss.com/wp-content/uploads/2014/05/Installing_Windows8_Ubuntu.jpeg" alt=""></p><p>安装窗口中你需要注意的是<strong>安装类型（Installation Type）</strong>。选择这里的<strong>其它选项（Something else）</strong>：</p><p><img src="http://itsfoss.com/wp-content/uploads/2014/05/Installing_Windows8_Ubuntu_1.jpeg" alt=""></p><p>还记得我们事先划分的未分配空间吗？我们将用它来创建根分区（ / ），交换空间（Swap）以及家目录（Home）。选择空闲（free space）然后点击加号（+）。</p><p><img src="http://itsfoss.com/wp-content/uploads/2014/05/Installing_Windows8_Ubuntu_2.jpeg" alt=""></p><p>它会给你提供创建Linux分区的选项。我们正在创建根分区 /。10到20GB空间就足够了。选择大小（Size），然后选择Ext 4作为文件系统以及 /（意思是根）作为挂载点（Mount point）。</p><p><img src="http://itsfoss.com/wp-content/uploads/2014/05/Installing_Windows8_Ubuntu_3.png" alt=""></p><p>点击确定会回到分区界面。下一步我们创建交换空间（Swap）。像之前一样，再次点击加号（+）。这次我们选择作为交换空间（Swap area）。建议的交换空间大小是物理内存的两倍。</p><p><img src="http://itsfoss.com/wp-content/uploads/2014/05/Installing_Windows8_Ubuntu_4.png" alt=""></p><p>以同样的方式创建家目录（Home）。给它分配最大的空间（实际上是给它分配剩余的所有空间），因为这是你会用来存储音乐，图片以及下载的文件的位置。</p><p><img src="http://itsfoss.com/wp-content/uploads/2014/05/Installing_Windows8_Ubuntu_5.png" alt=""></p><p>分配好了根分区（ / ），交换空间（Swap）和家目录（Home）之后，点击<strong>现在安装（Install Now）</strong>：</p><p><img src="http://itsfoss.com/wp-content/uploads/2014/05/Installing_Windows8_Ubuntu_6.jpeg" alt=""></p><p>好了，你现在基本上以及赢得了这场战役了~露出胜利的微笑吧~接下来你会被要求设置用户名密码等等。基本上你现在只需点击下一步。</p><p>一旦安装完成，重新启动电脑，你应该会看到紫色的grub欢迎界面。尽情享受Ubuntu和Windows 8的双启动模式吧。（译注：对于可能出现grub系统选择中没有Windows 8选项或是无法正常启动的情况，可搜索Boot Repair工具的使用）</p><p>我希望这份指南能够帮你实现Ubuntu和Windows 8的UEFI模式双启动。虽然这篇文章是为Ubuntu写的，它对其它的Linux OS应该也有所帮助。欢迎提出任何问题与建议。</p><hr>',21)),o("p",null,[t[15]||(t[15]=n("via: ",-1)),i(s,{href:"http://itsfoss.com/install-ubuntu-1404-dual-boot-mode-windows-8-81-uefi/"},{default:u(()=>[...t[14]||(t[14]=[n("http://itsfoss.com/install-ubuntu-1404-dual-boot-mode-windows-8-81-uefi/",-1)])]),_:1})]),o("p",null,[t[18]||(t[18]=n("译者：",-1)),i(s,{href:"https://github.com/alim0x"},{default:u(()=>[...t[16]||(t[16]=[n("alim0x",-1)])]),_:1}),t[19]||(t[19]=n(" 校对：",-1)),i(s,{href:"https://github.com/wxy"},{default:u(()=>[...t[17]||(t[17]=[n("wxy",-1)])]),_:1})]),o("p",null,[t[22]||(t[22]=n("本文由 ",-1)),i(s,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...t[20]||(t[20]=[n("LCTT",-1)])]),_:1}),t[23]||(t[23]=n(" 原创翻译，",-1)),i(s,{href:"http://linux.cn/"},{default:u(()=>[...t[21]||(t[21]=[n("Linux中国",-1)])]),_:1}),t[24]||(t[24]=n(" 荣誉推出",-1))])])}const T=p(r,[["render",w]]);export{x as __pageData,T as default};
